from nokia_nom_open_api_client import (ConfigurationPostPlanRequest,
                                       ConfigurationUpdatePlanRequest, MOIdsRequest,
                                       DescendantMoLitesRequest,
                                       RelatedMOsRequest, ConfigurationUpdatePlanRequestInfo,
                                       ConfigurationPostPlanRequestInfo,
                                       ManagedObjectsCreateUpdateRequest, DeleteManagedObjectsRequest)

from taf.nms.nom.schemas.cm.descendant_mo_lites_response import DescendantMoLitesResponse
from taf.nms.nom.schemas.cm.get_managed_objects_response import GetManagedObjectsResponse
from taf.nms.nom.schemas.cm.configuration_get_plan_response import ConfigurationGetPlanResponse
from taf.nms.nom.schemas.cm.mo_lites_response import MoLitesResponse
from taf.nms.nom.schemas.cm.configuration_post_plan_response import ConfigurationPostPlanResponse
from taf.nms.nom.schemas.cm.related_mo_lites_response import RelatedMoLitesResponse

import nokia_nom_open_api_client.models
from nokia_nom_open_api_client.models import ManagedObjectsMoClassMoClass, ManagedObjectsInfo


class PatchedManagedObjectsMoClassMoClass(ManagedObjectsMoClassMoClass):
    # Disable raising ValueError exception when version is set to None.
    # Otherwise ManagedObjectsMoClassMoClass schema in nom_2007_openapi.yaml has to be modified
    # (each time new spec version is provided) to accept None as value by setting 'nullable: true'
    @ManagedObjectsMoClassMoClass.version.setter
    def version(self, version):
        self._version = version


nokia_nom_open_api_client.models.ManagedObjectsMoClassMoClass = PatchedManagedObjectsMoClassMoClass


class PatchedManagedObjectsInfo(ManagedObjectsInfo):
    # Set parameters to object instead of ManagedObjectsParameters
    # in order to deserialize correctly server response and return the all actual MOC's parameters.
    # Otherwise the ones not defined as ManagedObjectsParameters' properties are skipped.
    openapi_types = {
        'mo_id': 'str',
        'mo_class': 'ManagedObjectsMoClassMoClass',
        'operation': 'str',
        'parameters': 'object'
    }

    # Disable raising ValueError exception when operation is set to None.
    # Otherwise ManagedObjectsInfo schema in nom_2007_openapi.yaml has to be modified
    # (each time new spec version is provided) to accept None as value by setting 'nullable: true'
    @ManagedObjectsInfo.operation.setter
    def operation(self, operation):
        allowed_values = ["UPDATE", "CREATE", "DELETE", None]
        if self.local_vars_configuration.client_side_validation and operation not in allowed_values:
            raise ValueError(
                "Invalid value for `operation` ({0}), must be one of {1}"
                .format(operation, allowed_values)
            )
        self._operation = operation


nokia_nom_open_api_client.models.ManagedObjectsInfo = PatchedManagedObjectsInfo


class CM(object):
    def __init__(self, api_client):
        """
        :param DefaultApi api_client:
        """
        self.api_client = api_client

    def create_empty_plan(self, plan_name, description, plan_type):
        configuration_post_plan_request = ConfigurationPostPlanRequest(type=plan_type,
                                                                       info=ConfigurationPostPlanRequestInfo(
                                                                           name=plan_name,
                                                                           description=description
                                                                       ))
        return ConfigurationPostPlanResponse.from_object_dict(self.api_client.api_cm_data_v1_configuration_post(
            configuration_post_plan_request=configuration_post_plan_request))

    def update_plan_header_information(self, plan_name, description, plan_type, conf_id):
        configuration_update_plan_request = ConfigurationUpdatePlanRequest(type=plan_type,
                                                                           info=ConfigurationUpdatePlanRequestInfo(
                                                                               name=plan_name,
                                                                               description=description,
                                                                               conf_id=conf_id
                                                                           ))
        return self.api_client.api_cm_data_v1_configuration_patch(
            configuration_update_plan_request=configuration_update_plan_request)

    def get_plan_header_info(self, plan_type, conf_id):
        return ConfigurationGetPlanResponse.from_object_dict(
            self.api_client.api_cm_data_v1_configuration_get(type=plan_type, conf_id=conf_id))

    def delete_plan(self, conf_id):
        return self.api_client.api_cm_data_v1_configuration_delete(conf_id=conf_id)

    def get_mo_lites_for_managed_objects(self, conf_id, mo_ids):
        mo_ids_request = MOIdsRequest(conf_id=conf_id, mo_ids=mo_ids)
        return MoLitesResponse.from_object_dict(
            self.api_client.api_cm_data_v1_mo_lites_post(mo_ids_request=mo_ids_request))

    def get_managed_objects_parameters(self, conf_id, mo_ids):
        mo_ids_request = MOIdsRequest(conf_id=conf_id, mo_ids=mo_ids)
        return GetManagedObjectsResponse.from_object_dict(self.api_client.api_cm_data_v1_get_managed_objects_post(
            mo_ids_request=mo_ids_request))

    @staticmethod
    def _convert_manage_objects(managed_objects):
        _managed_objects = []
        for mo in managed_objects:
            if isinstance(mo, ManagedObjectsInfo):
                _managed_objects.append(mo)
            else:
                mo['mo_id'] = mo.pop('moId', None) or mo.pop('mo_id')
                mo['mo_class'] = mo.pop('moClass', None) or mo.pop('mo_class')
                mo['operation'] = mo.pop('planOperation', None) or mo.pop('operation')
                _managed_objects.append(ManagedObjectsInfo(**mo))
        return _managed_objects

    def add_managed_objects(self, conf_id, managed_objects):
        managed_objects_create_update_request = ManagedObjectsCreateUpdateRequest(
            conf_id=conf_id, managed_objects=self._convert_manage_objects(managed_objects))
        self.api_client.api_cm_data_v1_managed_objects_post(
            managed_objects_create_update_request=managed_objects_create_update_request)

    def edit_managed_objects(self, conf_id, managed_objects):
        managed_objects_create_update_request = ManagedObjectsCreateUpdateRequest(
            conf_id=conf_id, managed_objects=self._convert_manage_objects(managed_objects))
        self.api_client.api_cm_data_v1_managed_objects_put(
            managed_objects_create_update_request=managed_objects_create_update_request)

    def delete_managed_objects(self, conf_id, mo_ids):
        delete_managed_objects_request = DeleteManagedObjectsRequest(
            conf_id=conf_id, mo_ids=mo_ids)
        self.api_client.api_cm_data_v1_delete_managed_objects_post(
            delete_managed_objects_request=delete_managed_objects_request)

    def get_descendant_managed_objects(self, conf_id, mo_ids, mo_classes):
        descendant_mo_lites_request = DescendantMoLitesRequest(conf_id=conf_id, mo_ids=mo_ids, mo_classes=mo_classes)
        return DescendantMoLitesResponse.from_object_dict(self.api_client.api_cm_data_v1_descendant_mo_lites_post(
            descendant_mo_lites_request=descendant_mo_lites_request))

    def get_mo_lites_related_to_managed_objects(self, conf_id, mo_ids, relationship_id):
        related_m_os_request = RelatedMOsRequest(conf_id=conf_id, mo_ids=mo_ids, relationship_id=relationship_id)
        return RelatedMoLitesResponse.from_object_dict(
            self.api_client.api_cm_data_v1_related_mo_lites_post(related_m_os_request=related_m_os_request))

    def get_mo_lites_for_root_managed_objects(self, conf_id):
        return MoLitesResponse.from_object_dict(self.api_client.api_cm_data_v1_root_mo_lites_get(conf_id=conf_id))

    def import_cnf_plan(self, cnf_deployment_plan_name, plan_type, cnf_deployment_data,
                        override=True, description=None, **kwargs):
        if 'secret_paths' in kwargs and not kwargs['secret_paths']:
            del kwargs['secret_paths']
        return self.api_client.api_cm_data_v1_deployments_plans_post(
            cnf_deployment_plan_name=cnf_deployment_plan_name, override=override,
            plan_type=plan_type, description=description,
            cnf_deployment_data=cnf_deployment_data, **kwargs
        )
